const crypto = require('crypto');
const h = $json.headers || {};
const ts = String(h['x-superbot-timestamp'] || '');
const nonce = String(h['x-superbot-nonce'] || '');
const sig = String(h['x-superbot-signature'] || '');
const raw = typeof $json.body === 'string' ? $json.body : JSON.stringify($json.body);
const msg = ts + '.' + nonce + '.' + raw;
const key = $env.SUPERBOT_WEBHOOK_SECRET;
const expected = crypto.createHmac('sha256', key).update(msg).digest('hex');
if (!crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(sig))) {
  throw new Error('Invalid signature');
}
return [{ json: $json.body }];

const body = $json;
const text = "RISK BREAKER TRIGGERED: " + (body.reason || "unknown") + "\n" +
  "Venue: " + (body.venue || "unknown") + "\n" +
  "Value: " + (body.value !== undefined ? body.value : "unknown") + "\n" +
  "Threshold: " + (body.threshold !== undefined ? body.threshold : "unknown") + "\n" +
  "Action: " + (body.action || "halt") + "\n" +
  "Timestamp: " + (body.ts || new Date().toISOString());
return [{ json: { text, severity: "critical", reason: body.reason, venue: body.venue } }];
